    /**
     * Method to retrieve the Agent via AgentFetchOneSummary
     * @param 	summary AgentFetchOneSummary 
     * @return 	AgentFetchOneResponse
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    public Agent getAgent( AgentFetchOneSummary summary ) 
    throws ProcessingException, IllegalArgumentException {
    	
    	if( summary == null )
    		throw new IllegalArgumentException( "AgentFetchOneSummary arg cannot be null" );
    	
    	Agent entity = null;
    	
        try {
        	// --------------------------------------
        	// validate the fetch one summary
        	// --------------------------------------    	
        	validator.validate( summary );    
        	
        	// --------------------------------------
        	// use queryGateway to send request to Find a Agent
        	// --------------------------------------
        	CompletableFuture<Agent> futureEntity = queryGateway.query(new FindAgentQuery( new LoadAgentFilter( summary.getAgentId() ) ), ResponseTypes.instanceOf(Agent.class));
        	
        	entity = futureEntity.get();
        }
        catch( Exception exc ) {
            final String errMsg = "Unable to locate Agent with id " + summary.getAgentId();
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return entity;
    }


